void Dobrar(ref int numero)
{
    numero = numero * 2;
}

bool TentarDividir(int a, int b, out int resultado)
{
    if (b == 0) { resultado = 0; return false; }
    resultado = a / b;
    return true;
}

int Somar(params int[] numeros)
{
    int total = 0;
    foreach (int n in numeros) total += n;
    return total;
}

int valor = 5;
Dobrar(ref valor); // valor agora é 10

TentarDividir(10, 2, out int divisao); // divisao = 5

int soma = Somar(1, 2, 3, 4); // soma = 10

public class ContaBancaria
{
    private decimal saldo; // só a própria classe acessa diretamente

    public string Titular { get; }

    public ContaBancaria(string titular)
    {
        Titular = titular;
        saldo = 0;
    }

    public void Depositar(decimal valor)
    {
        if (valor > 0) saldo += valor;
    }

    public decimal ConsultarSaldo() => saldo;
}

ContaBancaria conta = new ContaBancaria("Ana");
conta.Depositar(100);
Console.WriteLine(conta.ConsultarSaldo()); // 100

public class Animal
{
    public string Nome { get; set; } = "";

    public virtual string EmitirSom() => "...";
}

public class Cachorro : Animal
{
    public override string EmitirSom() => "Au au!";
}

Cachorro rex = new Cachorro { Nome = "Rex" };
Console.WriteLine(rex.EmitirSom()); // Au au!

List<Animal> animais = new List<Animal>
{
    new Cachorro { Nome = "Rex" },
    new Gato { Nome = "Mia" }
};

foreach (Animal animal in animais)
{
    // cada objeto executa sua própria versão de EmitirSom
    Console.WriteLine($"{animal.Nome}: {animal.EmitirSom()}");
}

public abstract class FormaGeometrica
{
    public abstract double CalcularArea(); // sem corpo, obrigatório implementar

    public void Descrever() // implementação compartilhada
        => Console.WriteLine($"Área: {CalcularArea()}");
}

public interface IDesenhavel
{
    void Desenhar();
}

public class Circulo : FormaGeometrica, IDesenhavel
{
    public double Raio { get; set; }

    public override double CalcularArea() => Math.PI * Raio * Raio;

    public void Desenhar() => Console.WriteLine("Desenhando círculo");
}

