public class Caixa<T>
{
    public T Conteudo { get; set; }

    public Caixa(T conteudo)
    {
        Conteudo = conteudo;
    }
}

// método genérico com restrição (where)
public T Maior<T>(T a, T b) where T : IComparable<T>
{
    return a.CompareTo(b) > 0 ? a : b;
}

Caixa<int> caixaDeNumero = new Caixa<int>(42);
Caixa<string> caixaDeTexto = new Caixa<string>("olá");

int maiorNumero = Maior(10, 20); // 20

public delegate void Notificar(string mensagem);

public class Pedido
{
    public event Notificar? OnFechado;

    public void Fechar()
    {
        Console.WriteLine("Pedido fechado.");
        OnFechado?.Invoke("O pedido foi fechado!");
    }
}

Pedido pedido = new Pedido();

// se inscrevendo no evento com uma lambda expression
pedido.OnFechado += mensagem => Console.WriteLine($"Notificação: {mensagem}");

pedido.Fechar();

public static class StringExtensions
{
    public static bool EhPalindromo(this string texto)
    {
        string limpo = texto.Replace(" ", "").ToLower();
        char[] invertido = limpo.ToCharArray();
        Array.Reverse(invertido);
        return limpo == new string(invertido);
    }
}

// uso: parece um método nativo de string
bool resultado = "arara".EhPalindromo(); // true

(int Quociente, int Resto) Dividir(int a, int b)
{
    return (a / b, a % b);
}

// desconstrução direta em variáveis separadas
var (quociente, resto) = Dividir(17, 5);

Console.WriteLine($"Quociente: {quociente}, Resto: {resto}");

// também é possível acessar pelos nomes definidos na tupla
var resultado = Dividir(17, 5);
Console.WriteLine(resultado.Quociente);

// IQueryable: a consulta ainda não foi executada, é só uma descrição
IQueryable<Produto> consulta = dbContext.Produtos
    .Where(p => p.Preco > 100);

// só ao chamar ToList() a consulta é traduzida para SQL e executada no banco
List<Produto> produtosCaros = consulta.ToList();

// se converter para IEnumerable antes, o filtro passa a rodar em memória
IEnumerable<Produto> todosOsProdutos = dbContext.Produtos.AsEnumerable();
var filtradoEmMemoria = todosOsProdutos.Where(p => p.Preco > 100); // já trouxe tudo do banco antes de filtrar

// forma com bloco: o arquivo é fechado ao sair do bloco using
using (StreamReader leitor = new StreamReader("dados.txt"))
{
    string conteudo = leitor.ReadToEnd();
    Console.WriteLine(conteudo);
} // Dispose() chamado automaticamente aqui

// forma moderna (C# 8+): Dispose() ao final do escopo do método
void LerArquivo()
{
    using var leitor = new StreamReader("dados.txt");
    Console.WriteLine(leitor.ReadToEnd());
} // Dispose() chamado automaticamente ao sair do método

public class Calculadora
{
    public int Somar(int a, int b) => a + b;
}

public class CalculadoraTestes
{
    [Fact]
    public void Somar_DoisMaisDois_DeveRetornarQuatro()
    {
        var calculadora = new Calculadora();

        int resultado = calculadora.Somar(2, 2);

        Assert.Equal(4, resultado);
    }

    [Theory]
    [InlineData(1, 1, 2)]
    [InlineData(-1, 1, 0)]
    [InlineData(0, 0, 0)]
    public void Somar_VariosCasos_DeveRetornarSomaCorreta(int a, int b, int esperado)
    {
        var calculadora = new Calculadora();

        int resultado = calculadora.Somar(a, b);

        Assert.Equal(esperado, resultado);
    }
}
